DO $$
DECLARE
  m_id       INTEGER;
  cur        vr_measure_issues;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE congress = 119 AND chamber = 'house' AND number = 'H.R. 6644';
  IF m_id IS NULL THEN
    RAISE EXCEPTION 'Federal wave F4: H.R. 6644 (119, house) is not in vr_measures. This wave promotes an existing row and creates nothing, so a missing measure is a corpus problem and not something to insert around.';
  END IF;

  SELECT * INTO cur FROM vr_measure_issues
   WHERE measure_id = m_id AND issue_key = 'housing';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Federal wave F4: H.R. 6644 carries no housing row to promote. The row this wave read was filed by an earlier pack at weight 80, non-primary; if it has been retracted since, the promote is moot and this migration must be re-decided rather than made to insert one.';
  END IF;

  -- Idempotent second run: the flag is already set. Check that nothing else moved
  -- underneath it and stop. This is the branch a re-apply takes.
  IF cur.is_primary THEN
    IF cur.weight <> 80 OR cur.support_meaning <> 'yea_supports' THEN
      RAISE EXCEPTION 'Federal wave F4: H.R. 6644 housing is already primary but now reads weight %, support_meaning % rather than 80 / yea_supports. Something else has rewritten this row; roll forward with a new migration rather than letting this one overwrite it.', cur.weight, cur.support_meaning;
    END IF;
    RAISE NOTICE 'Federal wave F4: H.R. 6644 housing is already in the primary lane; nothing to do.';
    RETURN;
  END IF;

  -- FAIL-CLOSED ON THE PRE-STATE. Each of these three is a different way for the
  -- row to have stopped being the row this wave argued about, and each stops rather
  -- than adapts: the weight is what ranks housing below housing_build, the polarity
  -- is what every member's read direction comes from, and the rationale is another
  -- writer's text the moment it is not the one F2's pack wrote (runbook rule 21).
  IF cur.weight <> 80 THEN
    RAISE EXCEPTION 'Federal wave F4: expected H.R. 6644 housing at weight 80, found %. The promote deliberately does not move the weight — 80 is what keeps housing ranked below housing_build''s 100 — so a different weight means a different decision is needed.', cur.weight;
  END IF;
  IF cur.support_meaning <> 'yea_supports' THEN
    RAISE EXCEPTION 'Federal wave F4: expected H.R. 6644 housing support_meaning yea_supports, found %. This wave changes no polarity anywhere; if the live polarity has flipped, the primary lane would publish 193 members'' positions in a direction this wave never read.', cur.support_meaning;
  END IF;
  IF cur.rationale NOT LIKE 'Secondary:%' THEN
    RAISE EXCEPTION 'Federal wave F4: H.R. 6644 housing no longer carries the "Secondary:" rationale this wave read (found: %). Overwriting a rationale a later writer has since replaced is runbook rule 21 violated by a migration, so this stops instead.', left(cur.rationale, 120);
  END IF;

  UPDATE vr_measure_issues
     SET is_primary = TRUE,
         rationale  = 'Primary: the 21st Century ROAD to Housing Act is a housing act, and housing affordability is its own subject rather than a title inside a vehicle. `housing`''s published chip is ''Make housing more affordable by boosting supply and lowering the cost to build and buy'', and the enrolled text carries all three of those limbs as full titles: supply in Title I (Sec. 103 infill exemption, Sec. 104 publicly owned land database, Sec. 107 housing supply frameworks), Title II (Building More in America) and Title III (Manufactured Housing for America); the cost to build in Sec. 211, captioned the Housing Affordability Act, which raises the per-unit dollar limits on FHA multifamily mortgage insurance at 12 U.S.C. 1713(c)(3)(A) and 1715e(b)(2) roughly fourfold and re-indexes them to the Census Bureau''s Price Deflator Index of Multifamily Residential Units Under Construction; and the cost to buy in Title IV (Accessing the American Dream) — Sec. 401 small-dollar loan originator incentives, Sec. 402 small-dollar mortgage points and fees, Sec. 403 Appraisal Industry Improvement Act, Sec. 404 Helping More Families Save Act — in Title IX (Strengthening Community Banks'' Role in Housing) and in Title X (Home-Ownership for Main Street America), whose single section restricts large institutional-investor purchases of single-family homes. Eleven of the Act''s twelve titles are housing titles. Weighted 80 rather than 100 and ranked below the housing_build primary because supply is the limb the Act''s own long title names; the weight is what ranks the two axes, not the flag.',
         source_url = 'https://www.govinfo.gov/content/pkg/PLAW-119publ101/html/PLAW-119publ101.htm'
   WHERE id = cur.id;

  RAISE NOTICE 'Federal wave F4: H.R. 6644 housing promoted to the primary lane at weight 80.';
END $$;

