DO $$
DECLARE
  m_id            INTEGER;
  n_promoted      INTEGER;
  n_rows          INTEGER;
  n_build_primary INTEGER;
  n_own_chamber   INTEGER;
  n_sen_primary   INTEGER;
  n_refused       INTEGER;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE congress = 119 AND chamber = 'house' AND number = 'H.R. 6644';

  -- 1. The row landed, in the lane, at the weight and polarity it was filed at.
  SELECT count(*) INTO n_promoted FROM vr_measure_issues
   WHERE measure_id = m_id AND issue_key = 'housing'
     AND is_primary AND weight = 80 AND support_meaning = 'yea_supports';
  IF n_promoted <> 1 THEN
    RAISE EXCEPTION 'Federal wave F4: the housing w80 PRIMARY yea_supports row on H.R. 6644 (119) did not land (found % row(s)). Without it the primary wall reopens and 97 senators plus 96 representatives read incidental on housing again, which was the state this wave found.', n_promoted;
  END IF;

  -- 2. NO ROW WAS ADDED OR REMOVED. The measure carried four mappings before this
  --    migration and carries four after: housing_build 100, housing 80,
  --    permitting_reform 60, crypto_cbdc 40. This is the assertion that catches a
  --    promote that quietly became an ingest.
  SELECT count(*) INTO n_rows FROM vr_measure_issues WHERE measure_id = m_id;
  IF n_rows <> 4 THEN
    RAISE EXCEPTION 'Federal wave F4: H.R. 6644 now carries % issue row(s) rather than 4. This wave adds no mapping and removes none; housing_support and disaster_resilience were both read on this Act and refused in writing.', n_rows;
  END IF;

  -- 3. THE COUSIN WALL, AS AN ASSERTION. housing_build keeps the w100 primary, so
  --    vr-pack.ts still orders it above housing and the bill page's headline issue
  --    is unchanged. A promote that displaced it would be a different decision.
  SELECT count(*) INTO n_build_primary FROM vr_measure_issues
   WHERE measure_id = m_id AND issue_key = 'housing_build' AND is_primary AND weight = 100;
  IF n_build_primary <> 1 THEN
    RAISE EXCEPTION 'Federal wave F4: housing_build no longer holds the w100 primary on H.R. 6644 (found % row(s)). housing was promoted BESIDE it, not over it — the weight is what ranks the two axes and the supply limb is the one the Act''s own long title names.', n_build_primary;
  END IF;

  -- 4. Runbook rule 30's second corollary, checked rather than trusted: a measure
  --    whose own chamber does not appear among its rolls is almost always an ingest
  --    gap, and this wave hangs a primary flag on a House-origin measure.
  SELECT count(*) INTO n_own_chamber FROM vr_rollcalls
   WHERE measure_id = m_id AND chamber = 'house';
  IF n_own_chamber < 1 THEN
    RAISE EXCEPTION 'Federal wave F4: H.R. 6644 is a house measure and carries % roll call(s) in the house. The 96 House gains this wave measured come from that roll; without it the promote serves one chamber and leaves a written gap in the other.', n_own_chamber;
  END IF;

