  --    housing at is_primary must have a Senate roll, or the key is back to zero
  --    Senate-reachable PRIMARYs and all 97 senator rows go unread again.
  SELECT count(DISTINCT mi.measure_id) INTO n_sen_primary
    FROM vr_measure_issues mi
    JOIN vr_rollcalls rc ON rc.measure_id = mi.measure_id AND rc.chamber = 'senate'
   WHERE mi.issue_key = 'housing' AND mi.is_primary;
  IF n_sen_primary < 1 THEN
    RAISE EXCEPTION 'Federal wave F4: housing holds % Senate-reachable PRIMARY measure(s). Below 1 the primary wall in stance-helpers.js reopens; H.R. 6644''s Senate passage roll (119/2 roll 53, On Passage of the Bill, 89-10) is the only instrument in the 119th that closes this key.', n_sen_primary;
  END IF;

