  --    legitimately promotes one of these should roll forward with its own argument;
  --    this assertion exists so that it has to write one.
  SELECT count(*) INTO n_refused FROM vr_measure_issues mi JOIN vr_measures m ON m.id = mi.measure_id
   WHERE m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.R. 4'
     AND mi.issue_key = 'america_first' AND mi.is_primary;
