     AND mi.issue_key = 'water' AND mi.is_primary;
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: water was MEASURED AND REFUSED as a primary-lane promote on H.R. 3684 (117) and now reads primary. The argument it contradicts: a title of the infrastructure act. water''s scope is demand-side conservation, which is also why H.J.Res. 20 — a rule on gas-fired instantaneous water heaters — was refused as a keyword collision.';
  END IF;
  SELECT count(*) INTO n_refused FROM vr_measure_issues mi JOIN vr_measures m ON m.id = mi.measure_id
   WHERE m.congress = 117 AND m.chamber = 'house' AND m.number = 'H.R. 4346'
     AND mi.issue_key = 'econ_growth' AND mi.is_primary;
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: econ_growth was MEASURED AND REFUSED as a primary-lane promote on H.R. 4346 (117) and now reads primary. The argument it contradicts: Sec. 103 of CHIPS is an industrial-policy mechanism inside a research-and-fabrication act whose primary is tech_innovation w100.';
  END IF;
  SELECT count(*) INTO n_refused FROM vr_measure_issues mi JOIN vr_measures m ON m.id = mi.measure_id
   WHERE m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 37'
     AND mi.issue_key = 'econ_trade' AND mi.is_primary;
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: econ_trade was MEASURED AND REFUSED as a primary-lane promote on S.J.Res. 37 (119) and now reads primary. The argument it contradicts: refused on a surfaced polarity contradiction (rule 25): the corpus reads tariff-imposing proclamations AND this tariff-terminating resolution as both supporting econ_trade. Its own subject is the authority question, held correctly by tariffs_authority w100.';
  END IF;
  SELECT count(*) INTO n_refused FROM vr_measure_issues mi JOIN vr_measures m ON m.id = mi.measure_id
   WHERE m.congress = 117 AND m.chamber = 'senate' AND m.number = 'S. 2938'
     AND mi.issue_key = 'health_mental' AND mi.is_primary;
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: health_mental was MEASURED AND REFUSED as a primary-lane promote on S. 2938 (117) and now reads primary. The argument it contradicts: the Bipartisan Safer Communities Act is a firearms act (gun_safety w100). A large mental-health title does not make it a mental-health instrument.';
  END IF;
  SELECT count(*) INTO n_refused FROM vr_measure_issues mi JOIN vr_measures m ON m.id = mi.measure_id
   WHERE m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S. 331'
     AND mi.issue_key = 'health_mental' AND mi.is_primary;
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: health_mental was MEASURED AND REFUSED as a primary-lane promote on S. 331 (119) and now reads primary. The argument it contradicts: the HALT Fentanyl Act is a sentencing act (immig_fentanyl w100) and its health_mental slice is filed yea_opposes as a downstream consequence.';
  END IF;
  SELECT count(*) INTO n_refused FROM vr_measure_issues
   WHERE measure_id = m_id AND issue_key = 'housing_support';
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: housing_support was READ AND REFUSED as a new row on H.R. 6644 and now carries % row(s). The argument it contradicts: Secs. 404, 405, 212 and 501 are four subsidy provisions in a twelve-title Act; the chip requires eviction limits and renter protections the Act does not contain; and measured, a lone non-primary row gains 0 characterised rows and adds 98 unread ones.', n_refused;
  END IF;
  SELECT count(*) INTO n_refused FROM vr_measure_issues
   WHERE measure_id = m_id AND issue_key = 'disaster_resilience';
  IF n_refused <> 0 THEN
    RAISE EXCEPTION 'Federal wave F4: disaster_resilience was READ AND REFUSED as a new row on H.R. 6644 and now carries % row(s). The argument it contradicts: Sec. 504, the Reforming Disaster Recovery Act, is one section of twelve titles. A wave does not get to apply a looser package rule to its own instrument than to the ones it declines.', n_refused;
  END IF;
END $$;
